const CACHE='ultima-luz-v5';
const ASSETS=['./','./index.html','./style.css','./game.js','./game-core.js','./manifest.webmanifest','./assets/three.module.min.js','./assets/forest-ground.jpg','./assets/rain.m4a','./assets/fonts.css','./assets/icon.svg','./assets/icon-192.png','./assets/icon-512.png','./assets/icon-maskable.png','./game-assets.js','./forest-layout.js','./world-models.js','./assets/CREDITS.txt','./assets/models/cabin.glb','./assets/models/allosaurus.glb','./assets/GLTFLoader.js','./assets/BufferGeometryUtils.js','./assets/models/nature.glb','./assets/models/car.glb','./assets/models/arms.glb','./assets/models/revolver.glb','./assets/audio/Car_Hood_Open.m4a','./assets/audio/Car_Acceleration.m4a','./assets/audio/Car_Door_Open.m4a','./assets/audio/Car_Door_Close.m4a','./assets/audio/Car_Engine_Turning_Off.m4a','./assets/audio/Car_Engine_Start_Up.m4a','./assets/audio/Car_Hood_Close.m4a','./assets/audio/Car_Engine_Loop.m4a'];
self.addEventListener('install',event=>{event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(ASSETS)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('ultima-luz-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==location.origin)return;const url=new URL(event.request.url);if(!ASSETS.some(a=>new URL(a,self.registration.scope).pathname===url.pathname))return;event.respondWith(caches.match(event.request).then(cached=>cached||fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy))}return response}))) });
